import java.util.*;

public class Solution {
    static class AVL {
        static class Node {
            int val, h = 1;
            Node esq, dir;
            Node(int val) { this.val = val; }
        }

        Node raiz;

        static int h(Node n) { return n == null ? 0 : n.h; }

        void inserir(int v) { raiz = inserir(raiz, v); }

        private Node inserir(Node n, int v) {
            if (n == null) return new Node(v);
            if (v < n.val) n.esq = inserir(n.esq, v);
            else if (v > n.val) n.dir = inserir(n.dir, v);
            else return n;
            return balancear(n);
        }

        private static void atualizar(Node n) { n.h = 1 + Math.max(h(n.esq), h(n.dir)); }

        private static Node rotDir(Node y) {
            Node x = y.esq;
            y.esq = x.dir;
            x.dir = y;
            atualizar(y);
            atualizar(x);
            return x;
        }

        private static Node rotEsq(Node x) {
            Node y = x.dir;
            x.dir = y.esq;
            y.esq = x;
            atualizar(x);
            atualizar(y);
            return y;
        }

        // fator > 1: pesado à esquerda (LL ou LR); fator < -1: pesado à direita (RR ou RL).
        private static Node balancear(Node n) {
            atualizar(n);
            int fator = h(n.esq) - h(n.dir);
            if (fator > 1) {
                if (h(n.esq.esq) < h(n.esq.dir)) n.esq = rotEsq(n.esq); // LR
                return rotDir(n);
            }
            if (fator < -1) {
                if (h(n.dir.dir) < h(n.dir.esq)) n.dir = rotDir(n.dir); // RL
                return rotEsq(n);
            }
            return n;
        }

        int altura() { return h(raiz); }

        List<Integer> emOrdem() {
            List<Integer> out = new ArrayList<>();
            Deque<Node> pilha = new ArrayDeque<>();
            Node n = raiz;
            while (n != null || !pilha.isEmpty()) {
                while (n != null) { pilha.push(n); n = n.esq; }
                n = pilha.pop();
                out.add(n.val);
                n = n.dir;
            }
            return out;
        }

        boolean balanceada() { return checar(raiz) >= 0; }

        private int checar(Node n) {
            if (n == null) return 0;
            int e = checar(n.esq), d = checar(n.dir);
            if (e < 0 || d < 0 || Math.abs(e - d) > 1) return -1;
            return 1 + Math.max(e, d);
        }
    }
}

