import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static Solution.AVL avl(int... vs) {
        var t = new Solution.AVL();
        for (int v : vs) t.inserir(v);
        return t;
    }

    @Test void quatroCasos() {
        for (int[] caso : new int[][]{{3, 2, 1}, {1, 2, 3}, {3, 1, 2}, {1, 3, 2}}) {
            var t = avl(caso);
            assertEquals(2, t.altura(), Arrays.toString(caso));
            assertEquals(2, t.raiz.val, Arrays.toString(caso));
            assertEquals(List.of(1, 2, 3), t.emOrdem());
        }
    }

    @Test void duplicatasIgnoradas() {
        assertEquals(List.of(1, 2), avl(2, 1, 2, 1).emOrdem());
    }

    @Test void crescenteFicaBaixa() {
        var t = new Solution.AVL();
        int n = 100_000;
        for (int i = 1; i <= n; i++) t.inserir(i);
        assertTrue(t.balanceada());
        assertTrue(t.altura() <= 1.44 * (Math.log(n) / Math.log(2)) + 2, "altura " + t.altura());
        assertEquals(n, t.emOrdem().size());
    }

    @Test void aleatoria() {
        var rnd = new Random(5);
        var t = new Solution.AVL();
        var ref = new TreeSet<Integer>();
        for (int i = 0; i < 20_000; i++) {
            int v = rnd.nextInt(50_000);
            t.inserir(v);
            ref.add(v);
        }
        assertTrue(t.balanceada());
        assertEquals(new ArrayList<>(ref), t.emOrdem());
    }
}
